// Kota kontrolu (19 Eyl 2026). Bu akista daha once HIC limit yoktu: webhook
// kimlik dogrulamasiz oldugu icin adresini bilen herkes sinirsiz cagirabiliyordu.
// Kota kullanici bazli: backend gercek kimligi govdede 'kkbKimlik' olarak
// yolluyor. WordPress'ten gelen giris yapmamis isteklerde bu alan olmaz, o
// zaman IP'ye duseriz. IP tek basina guvenilir degil (mobil veride degisir,
// ortak wifi'de birlesir), bu yuzden kimlik varsa o tercih edilir.
//
// ONEMLI: cikti girdinin AYNISI olmali, uzerine yalnizca bayrak eklenir.
// Alan beyaz listesi yapilirsa asagidaki dugumler body'yi bulamaz -- ayni
// hata 11 Eyl 2026'da 'Plan Yaniti'nda replik alanini dusurmustu.
const girdi = $input.first().json;
const kimlikGovde = girdi.body || girdi;
const ip = kimlikGovde.kkbKimlik || girdi.headers?.['x-forwarded-for']?.split(',')[0]?.trim() || girdi.headers?.['x-real-ip'] || 'unknown';
const today = new Date().toISOString().slice(0, 10);
const key = 'rl_aiv_' + ip + '_' + today;
const staticData = $getWorkflowStaticData('global');
if (!staticData.rateLimits) staticData.rateLimits = {};
// 7 gunden eski sayaclari sil, yoksa static data sinirsiz buyur.
const silSiniri = new Date(Date.now() - 7 * 86400000).toISOString().slice(0, 10);
for (const k of Object.keys(staticData.rateLimits)) {
  const kTarih = k.slice(-10);
  if (/^\d{4}-\d{2}-\d{2}$/.test(kTarih) && kTarih < silSiniri) delete staticData.rateLimits[k];
}
const current = staticData.rateLimits[key] || 0;
if (current >= 50) {
  return [{ json: { ...girdi, rateLimitExceeded: true } }];
}
staticData.rateLimits[key] = current + 1;
return [{ json: { ...girdi, rateLimitExceeded: false } }];

/**
 * KOTA YANITI -- gunluk sinir dolunca doner.
 *
 * Bu akis responseMode='lastNode' kullaniyor; HTTP 429 dondurmek icin butun
 * basari yollarina ayrica 'Respond to Webhook' dugumu eklemek gerekirdi.
 * Onun yerine akisin kendi hata kalibina uyuyoruz -- frontend zaten `error`
 * alanini kullaniciya gosteriyor.
 */
return [{ json: {
  // Backend bu isareti gorunce 429 dondurur; aylik hak ve kredi HARCANMAZ.
  _kotaDoldu: true,
  error: 'Günlük kullanım sınırına ulaştınız. Yarın tekrar deneyebilirsiniz.',
} }];

const body = $input.first().json.body || $input.first().json;
const prompt = body.prompt || '';
if (!prompt || prompt.length < 20) {
  return [{ json: { error: 'Geçersiz istek: prompt eksik.' } }];
}
const apiBody = {
  model: 'MiniMax-M3',
  max_completion_tokens: 8000,
  messages: [{ role: 'user', content: prompt }]
};
return [{ json: { ...body, apiBody } }];

// MiniMax-M3 reasoning modeli <think>...</think> blogu döndürür;
// gerçek JSON bundan sonra gelir. Think bloğunu atlayıp JSON'u çıkartıyoruz.
const apiData = $input.first().json;
let text = apiData.choices?.[0]?.message?.content || '';


// MiniMax-M3 reasoning (<think>) blogu: icindeki suslu parantezler JSON
// cikarimini bozuyordu (canlida tespit edildi) - blogu tamamen at.
const thinkEnd = text.lastIndexOf('</think>');
if (thinkEnd !== -1) text = text.slice(thinkEnd + '</think>'.length);

// ```json ... ``` sarmalayicisini kaldir
text = text.replace(/```(?:json)?/gi, '');

const jsonStart = text.indexOf('{');
const jsonEnd = text.lastIndexOf('}');
if (jsonStart !== -1 && jsonEnd !== -1) text = text.slice(jsonStart, jsonEnd + 1);

function tryParseJson(raw) {
  try { return JSON.parse(raw); } catch {
    const repaired = raw.replace(/,\s*([\]}])/g, '$1').replace(/[\u0000-\u0008\u000B\u000C\u000E-\u001F]/g, '');
    try { return JSON.parse(repaired); } catch { return null; }
  }
}

const result = tryParseJson(text);
if (!result) {
  return [{ json: {
    choices: [{ message: { content: text } }],
    _parseError: true
  }}];
}

return [{ json: {
  choices: [{ message: { content: JSON.stringify(result) } }]
}}];

const err = $input.first().json;
const msg = err?.error?.message || err?.message || JSON.stringify(err).slice(0, 200);
return [{ json: { error: 'MiniMax API hatası: ' + msg } }];
